local _KW_CHECK_URL = "https://api.pandauth.com/api/v1/public/getkey/purge/status"
local _KW_INTERVAL = 600
local _KW_MSG = "[Panda-Kryptic] No active key found for this device. Generate a key to continue."
local _KW_HS = game:GetService("HttpService")
local _KW_FILE = "PandaAuth_HWID.txt"
local _KW_BATCH = 12
local _KW_URL_MAX = 6000

local function _kwIdentities()
    local ids, seen = {}, {}
    local function push(s)
        local low = s:lower()
        if s == "" or seen[s] or low == "none" or low == "unknown" or low == "unknown_hwid" or low == "nil" then return end
        seen[s] = true
        ids[#ids + 1] = s
    end
    local function add(v)
        if v == nil then return end
        local s = tostring(v)
        push(s:sub(1, 1024))
        if #s > 1024 then push((s:gsub("[^%w_%-%.]", "")):sub(1, 1024)) end
    end
    local uid
    pcall(function()
        local lp = game:GetService("Players").LocalPlayer
        if lp and lp.UserId and lp.UserId ~= 0 then uid = tostring(lp.UserId) end
    end)
    if uid then add("rbx-" .. uid) end
    pcall(function()
        local sdk = (type(getgenv) == "function" and getgenv().PandaAuthV4) or _G.PandaAuthV4
        if type(sdk) == "table" and type(sdk.GetIdentity) == "function" then add(sdk.GetIdentity()) end
    end)
    pcall(function() if type(gethwid) == "function" then add(gethwid()) end end)
    pcall(function() if type(getfingerprintid) == "function" then add(getfingerprintid()) end end)
    pcall(function() if type(getdeviceid) == "function" then add(getdeviceid()) end end)
    pcall(function()
        if type(readfile) == "function" and (type(isfile) ~= "function" or isfile(_KW_FILE)) then
            add(readfile(_KW_FILE))
        end
    end)
    pcall(function()
        local cid = tostring(game:GetService("RbxAnalyticsService"):GetClientId())
        add(cid)
        add((cid:gsub("-", "")))
    end)
    if uid then
        add("PANDA_" .. uid)
        local named = false
        pcall(function()
            if type(identifyexecutor) == "function" then
                local ex = identifyexecutor()
                if ex ~= nil and tostring(ex) ~= "" then named = true; add("P_" .. uid .. "_" .. tostring(ex)) end
            end
        end)
        pcall(function()
            if type(getexecutorname) == "function" then
                local ex = getexecutorname()
                if ex ~= nil and tostring(ex) ~= "" then named = true; add("P_" .. uid .. "_" .. tostring(ex)) end
            end
        end)
        if not named then add("P_" .. uid .. "_unknown") end
    end
    return ids
end

local function _kwGet(url)
    local ok, resp = pcall(function() return game:HttpGet(url, true) end)
    if not ok or type(resp) ~= "string" then return nil end
    local ok2, decoded = pcall(function() return _KW_HS:JSONDecode(resp) end)
    if not ok2 or type(decoded) ~= "table" or decoded.success ~= true or type(decoded.data) ~= "table" then return nil end
    return decoded.data
end

local function _kwPoll()
    local ids = _kwIdentities()
    if #ids == 0 then return nil end
    local unknown = false
    local i = 1
    while i <= #ids do
        local url = _KW_CHECK_URL .. "?hwid=" .. _KW_HS:UrlEncode(ids[i])
        local j = i + 1
        while j <= #ids and j - i < _KW_BATCH do
            local part = "&alt=" .. _KW_HS:UrlEncode(ids[j])
            if #url + #part > _KW_URL_MAX then break end
            url = url .. part
            j = j + 1
        end
        local d = _kwGet(url)
        if d == nil then
            unknown = true
        elseif d.hasKey == true then
            return true
        elseif d.kw ~= 2 then
            for k = i + 1, j - 1 do
                local dk = _kwGet(_KW_CHECK_URL .. "?hwid=" .. _KW_HS:UrlEncode(ids[k]))
                if dk == nil then unknown = true elseif dk.hasKey == true then return true end
            end
        end
        i = j
    end
    if unknown then return nil end
    return false
end

