    while true do
        task.wait(_KW_INTERVAL)
        if _kwPoll() == false then
            task.wait(8)
            if _kwPoll() == false then
                pcall(function() warn(_KW_MSG) end)
                pcall(function() game:GetService("Players").LocalPlayer:Kick(_KW_MSG) end)
                break
            end
        end
    end
